/**
 * Architecture Contract: Blockchain Service
 *
 * Tests the public interface of services/blockchain.js in mock mode.
 * Verifies: token lifecycle, marketplace operations, event generation.
 *
 * mint() signature: (reservedTokenId, to, uri, licenseType, imageHash, licenseHash, ipfsUri)
 * delistToken() signature: (tokenId, licenseType, sellerAddress)
 *
 * If a refactoring breaks these tests, the interface has changed —
 * that's a breaking change, not a refactoring.
 *
 * Generated by /architect
 */

// Mock env must be set before require
process.env.USE_MOCK_BLOCKCHAIN = 'true';
process.env.NODE_ENV = 'test';

const blockchainService = require('../../src/services/blockchain');
const { createArchitectureCaptureSink } = require('./sinks/architecture-capture');

const WALLET = '0x1234567890123456789012345678901234567890';

/** Helper: reserve + mint a token */
async function mintToken(imageHash = '0xhash' + Date.now()) {
  const [r] = await blockchainService.reserveTokenId();
  const [result, events] = await blockchainService.mint(
    r.tokenId, WALLET, 'ipfs://uri', imageHash, 'ipfs://img'
  );
  return { tokenId: r.tokenId, result, events };
}

describe('Blockchain service interface contract', () => {
  beforeEach(() => {
    blockchainService.resetMock();
  });

  // ── Token Reservation ──

  test('reserveTokenId returns [result, events] tuple', async () => {
    const [result, events] = await blockchainService.reserveTokenId();

    expect(typeof result.tokenId).toBe('number');
    expect(typeof result.transactionHash).toBe('string');
    expect(Array.isArray(events)).toBe(true);
    expect(events.length).toBeGreaterThan(0);
    expect(events[0].type).toBe('token.reserved');
  });

  test('sequential reservations produce unique token IDs', async () => {
    const [r1] = await blockchainService.reserveTokenId();
    const [r2] = await blockchainService.reserveTokenId();
    expect(r1.tokenId).not.toBe(r2.tokenId);
  });

  // ── Minting ──

  test('mint returns [result, events] tuple with token data', async () => {
    const { result, events } = await mintToken('0xhash123');

    expect(typeof result.tokenId).toBe('number');
    expect(typeof result.transactionHash).toBe('string');
    expect(events.some(e => e.type === 'token.minted')).toBe(true);
  });

  test('isImageRegistered returns true for minted image hash', async () => {
    await mintToken('0xunique-hash');

    const registered = await blockchainService.isImageRegistered('0xunique-hash');
    expect(registered).toBe(true);
  });

  test('isImageRegistered returns false for unknown hash', async () => {
    const registered = await blockchainService.isImageRegistered('0xnonexistent');
    expect(registered).toBe(false);
  });

  // ── Token Queries ──

  test('getTokenData returns token metadata after mint', async () => {
    const { tokenId } = await mintToken('0xhash-query');

    const data = await blockchainService.getTokenData(tokenId);

    expect(data).toBeDefined();
    expect(data.creator.toLowerCase()).toBe(WALLET.toLowerCase());
    expect(data.ipfsUri).toBe('ipfs://img');
  });

  test('totalSupply increments after each mint', async () => {
    const before = await blockchainService.totalSupply();
    await mintToken('0xhash-supply');
    const after = await blockchainService.totalSupply();

    expect(after).toBe(before + 1);
  });

  // ── Marketplace ──

  test('listToken returns [result, events] with token.listed event', async () => {
    const { tokenId } = await mintToken('0xh1');

    const [result, events] = await blockchainService.listToken(
      tokenId, '1000000000000000000', 0, '0xlicensehash', 0, '0xsig', WALLET
    );

    expect(result).toBeDefined();
    expect(events.some(e => e.type === 'token.listed')).toBe(true);
  });

  test('getActiveListings returns currently listed tokens', async () => {
    const { tokenId } = await mintToken('0xh2');
    await blockchainService.listToken(tokenId, '1000000000000000000', 0, '0xlh', 0, '0xsig', WALLET);

    const listings = await blockchainService.getActiveListings();
    expect(listings.length).toBeGreaterThan(0);
    expect(listings.some(l => l.tokenId === tokenId)).toBe(true);
  });

  test('delistToken removes a listing', async () => {
    const { tokenId } = await mintToken('0xh3');
    await blockchainService.listToken(tokenId, '1000000000000000000', 0, '0xlh', 0, '0xsig', WALLET);

    // delistToken requires (tokenId, licenseType, sellerAddress)
    const [, events] = await blockchainService.delistToken(tokenId, 0, WALLET);
    expect(events.some(e => e.type === 'token.delisted')).toBe(true);
  });

  // ── EIP-712 ──

  test('getEIP712Domain returns domain with required fields', async () => {
    const domain = await blockchainService.getEIP712Domain();
    expect(domain).toHaveProperty('name');
    expect(domain).toHaveProperty('version');
    expect(domain).toHaveProperty('chainId');
    expect(domain).toHaveProperty('verifyingContract');
  });

  test('getNonce returns a number for any address', async () => {
    const nonce = await blockchainService.getNonce('0x0000000000000000000000000000000000000001');
    expect(typeof nonce).toBe('number');
  });

  // ── License Type Enum ──

  test('LicenseType enum has Display=0, Commercial=1, Transfer=2', () => {
    expect(blockchainService.LicenseType.Display).toBe(0);
    expect(blockchainService.LicenseType.Commercial).toBe(1);
    expect(blockchainService.LicenseType.Transfer).toBe(2);
  });
});
